const input = $json.body ?? $json;
const classification = String(input.response_classification ?? "").toLowerCase();
const counteroffer = Number(input.counteroffer_amount);
const mao = Number(input.dynamic_mao ?? input.adjusted_mao);
const motivation = String(input.motivation ?? "").toLowerCase();
const dealId = input.deal_id;
const leadId = input.lead_id;
const propertyId = input.property_id;
const dispatchId = input.dispatch_id;
const dnc = input.dnc === true || input.do_not_contact === true;
const blockers = Array.isArray(input.blockers) ? input.blockers : [];

const identityReady = Boolean(dealId && leadId && propertyId);
const validMao = Number.isFinite(mao) && mao >= 0;
const validCounter = classification !== "counteroffer" || (Number.isFinite(counteroffer) && counteroffer >= 0);
const blocked = dnc || blockers.length > 0;

let decision = "needs_review";
let strategy = "human_review";
let nextWorkflow = "WF-339";
let reason = "Seller response requires negotiation decisioning.";

if (!identityReady || !validMao || !validCounter) {
  decision = "incomplete";
  strategy = "collect_missing_evidence";
  nextWorkflow = "WF-126";
  reason = "Deal identity, dynamic MAO, or counteroffer data is incomplete/invalid.";
} else if (blocked || classification === "dnc") {
  decision = "blocked";
  strategy = "stop_communication";
  nextWorkflow = "WF-126";
  reason = "DNC or active blockers prevent automated negotiation.";
} else if (classification === "accepted") {
  decision = "acceptance_ready";
  strategy = "move_to_contract_review";
  nextWorkflow = "WF-339";
  reason = "Seller accepted the offer; contract readiness review can begin.";
} else if (classification === "counteroffer") {
  if (counteroffer <= mao) {
    const nearMao = counteroffer >= mao * 0.95;
    if (nearMao) {
      decision = "counteroffer_near_mao";
      strategy = "controlled_accept_or_revise";
      nextWorkflow = "WF-339";
      reason = "Counteroffer is within MAO but close enough to the ceiling to require controlled review.";
    } else {
      decision = "counteroffer_within_mao";
      strategy = "evaluate_counteroffer";
      nextWorkflow = "WF-339";
      reason = "Counteroffer is within the dynamic MAO ceiling.";
    }
  } else {
    decision = "counteroffer_above_mao";
    strategy = "revised_offer_or_reengagement";
    nextWorkflow = "WF-340";
    reason = "Counteroffer exceeds dynamic MAO; autonomous acceptance is prohibited.";
  }
} else if (classification === "rejected") {
  decision = "rejection_reengagement";
  strategy = "reengage_with_cadence";
  nextWorkflow = "WF-340";
  reason = "Seller rejected the current offer; controlled re-engagement may be appropriate.";
} else if (classification === "price_question" || classification === "question") {
  decision = "clarification_required";
  strategy = "answer_and_continue_negotiation";
  nextWorkflow = "WF-339";
  reason = "Seller needs clarification before negotiation can advance.";
} else if (classification === "other_response") {
  decision = "needs_review";
  strategy = "human_review";
  nextWorkflow = "WF-126";
  reason = "Response intent is not sufficiently clear for autonomous negotiation.";
}

const motivationBoost = /(urgent|distress|high)/i.test(motivation);
if (motivationBoost && decision === "rejection_reengagement") strategy = "high_motivation_reengagement";

return [{
  json: {
    ...input,
    workflow_id: "WF-338",
    controller_status: decision,
    negotiation_decision: decision,
    negotiation_strategy: strategy,
    dynamic_mao: validMao ? mao : null,
    counteroffer_amount: Number.isFinite(counteroffer) ? counteroffer : null,
    deal_id: dealId,
    lead_id: leadId,
    property_id: propertyId,
    dispatch_id: dispatchId,
    mao_protected: true,
    reason,
    next_workflow: nextWorkflow,
    requires_human_review: ["acceptance_ready", "counteroffer_near_mao", "clarification_required", "needs_review"].includes(decision),
    idempotency_key: input.idempotency_key ?? \`wf-338:\${dispatchId ?? "unknown"}:\${decision}:\${Number.isFinite(counteroffer) ? counteroffer : "none"}\`
  }
}];
